<template><main class="zj-workspace" v-loading="loading"><el-alert v-if="error" title="项目加载失败，请刷新重试" type="error" :closable="false"/><template v-if="project"><header class="zj-heading"><div><div class="zj-eyebrow">众基消防 / {{projectTypes[project.projectType]}}</div><h1>{{project.projectName}}</h1><p>{{project.projectNo}} · {{project.contractName||'待关联合同'}}</p></div><div><el-button @click="back">返回列表</el-button><el-button icon="Refresh" aria-label="刷新项目" @click="refresh"/></div></header><el-alert v-if="!project.contractId||project.numberPending||project.classificationPending" title="此历史项目存在待确认信息，请核对所属合同、类型或编号；原始记录已保留。" type="warning" :closable="false"/>
<section class="zj-card" style="margin-top:16px"><el-tabs v-model="active" :before-leave="beforeTab" @tab-change="loadTab"><el-tab-pane label="基本信息" name="basic"><div class="zj-summary"><span>正式编号：{{project.projectNo}}</span><el-button v-if="project.numberPending&&canEdit" text type="primary" :loading="saving" @click="applyNumber">申请正式编号</el-button></div><el-form v-if="project.classificationPending" label-position="top" :disabled="!canEdit"><el-form-item label="核实项目类型"><el-select v-model="basic.projectType" @change="basic.contractId=null"><el-option v-for="(label,code) in projectTypes" :key="code" :label="label" :value="code"/></el-select></el-form-item><el-checkbox v-model="basic.classificationPending" :true-value="false" :false-value="true">类型已核实</el-checkbox></el-form><ProjectBasicForm ref="basicRef" v-model="basic" :project-type="basic.projectType" :legacy="!project.contractId" :disabled="!canEdit||saving"/></el-tab-pane>
<el-tab-pane label="详细信息" name="details"><el-form label-position="top" :disabled="!canEdit||saving"><div class="zj-grid"><el-form-item v-for="f in detailFields" :key="f.key" :label="f.label"><el-input v-model="details[f.key]" :type="f.multi?'textarea':'text'" :rows="f.multi?4:undefined" :maxlength="f.multi?5000:500"/></el-form-item></div></el-form><el-collapse v-if="details.legacySystem"><el-collapse-item title="迁移的原项目系统资料（原样保留）"><pre style="white-space:pre-wrap;overflow-wrap:anywhere;max-height:400px;overflow:auto">{{details.legacySystem}}</pre></el-collapse-item></el-collapse></el-tab-pane>
<el-tab-pane label="登记信息" name="registration"><el-form label-position="top" :disabled="!canEdit||saving"><div class="zj-grid"><el-form-item label="现场情况"><el-select v-model="registration.visitStatus"><el-option label="未登记" value="unknown"/><el-option label="尚未到场" value="not_started"/><el-option label="已经到场" value="visited"/><el-option label="现场工作完成" value="completed"/></el-select></el-form-item><el-form-item label="实际到场日期"><el-date-picker v-model="registration.visitDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="报告情况"><el-select v-model="registration.reportStatus"><el-option label="未登记" value="unknown"/><el-option label="尚未制作" value="not_started"/><el-option label="制作中" value="in_progress"/><el-option label="报告已完成" value="completed"/></el-select></el-form-item><el-form-item label="报告完成日期"><el-date-picker v-model="registration.reportDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="报告编号"><el-input v-model="registration.reportNo" maxlength="255"/></el-form-item><el-form-item label="登记说明"><el-input v-model="registration.notes" type="textarea" :rows="4" maxlength="5000"/></el-form-item></div></el-form></el-tab-pane>
<el-tab-pane label="问题信息" name="issues"><div class="zj-summary"><span>记录现场排查发现的问题及整改进展</span><el-button v-if="canEdit" type="primary" icon="Plus" @click="editChild('issues')">登记问题</el-button></div><el-table :data="children.issues" v-loading="childLoading"><el-table-column prop="title" label="问题" min-width="220"/><el-table-column label="程度" width="100"><template #default="{row}">{{labels[row.severity]}}</template></el-table-column><el-table-column label="进展" width="100"><template #default="{row}">{{labels[row.status]}}</template></el-table-column><el-table-column prop="foundDate" label="发现日期" width="130"/><el-table-column prop="resolvedDate" label="解决日期" width="130"/><el-table-column label="操作" width="130"><template #default="{row}"><el-button link type="primary" @click="editChild('issues',row)">{{canEdit?'编辑':'查看'}}</el-button><el-button v-if="canEdit" link type="danger" @click="removeChild('issues',row)">删除</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane label="备注信息" name="notes"><el-input v-model="notes" type="textarea" :rows="12" maxlength="10000" show-word-limit :disabled="!canEdit||saving" placeholder="记录项目补充说明、沟通情况和需要注意的事项"/></el-tab-pane>
<el-tab-pane label="计划信息" name="plans"><div class="zj-summary"><span>安排现场、完工、出报告等工作节点</span><el-button v-if="canEdit" type="primary" icon="Plus" @click="editChild('plans')">创建计划</el-button></div><el-table :data="children.plans" v-loading="childLoading"><el-table-column prop="title" label="工作事项" min-width="200"/><el-table-column label="类型" width="110"><template #default="{row}">{{labels[row.planType]}}</template></el-table-column><el-table-column prop="startDate" label="计划开始" width="130"/><el-table-column prop="endDate" label="计划完成" width="130"/><el-table-column label="状态" width="110"><template #default="{row}">{{labels[row.status]}}</template></el-table-column><el-table-column label="操作" width="130"><template #default="{row}"><el-button link type="primary" @click="editChild('plans',row)">{{canEdit?'编辑':'查看'}}</el-button><el-button v-if="canEdit" link type="danger" @click="removeChild('plans',row)">删除</el-button></template></el-table-column></el-table></el-tab-pane>
<el-tab-pane v-if="canExpenses" label="报账信息" name="expenses"><div class="zj-summary"><strong>已登记金额：¥{{money(expenseSummary.totalAmount)}}</strong><span>{{expenseSummary.records||0}} 条记录</span><span v-if="expenseSummary.unassignedRecords">其中 {{expenseSummary.unassignedRecords}} 条人员归属待确认</span></div><el-alert title="此处为只读总览。历史参与人员原文保留，不将多人费用擅自分摊；报账入口后续建设。" type="info" :closable="false"/><el-alert v-if="legacyAmounts.length" :title="'历史账面汇总：'+legacyAmounts.join('、')+' 元；与已登记明细金额分别保留，不自动改账。'" type="warning" :closable="false"/><h3>按用户汇总</h3><el-table :data="expenseUsers"><el-table-column label="用户"><template #default="{row}">{{row.userName}}<el-tag v-if="!row.userId" size="small" type="warning">归属待确认</el-tag></template></el-table-column><el-table-column prop="records" label="记录数" width="100"/><el-table-column label="登记金额" align="right" width="180"><template #default="{row}">{{money(row.totalAmount)}}</template></el-table-column></el-table><h3>报账明细</h3><el-table :data="children.expenses" v-loading="childLoading"><el-table-column label="用户" min-width="160"><template #default="{row}">{{row.userName||'归属待确认'}}<div class="zj-sub">原参与人员：{{row.participant||'未填写'}}</div></template></el-table-column><el-table-column label="金额" align="right" width="140"><template #default="{row}">{{money(row.amount)}}</template></el-table-column><el-table-column prop="date" label="日期" width="180"/><el-table-column prop="remark" label="说明" min-width="200"/><el-table-column label="附件" width="100"><template #default="{row}"><el-link v-if="row.attachment" :href="fileUrl(row.attachment)" target="_blank">查看附件</el-link><span v-else>无</span></template></el-table-column></el-table></el-tab-pane></el-tabs>
<el-alert v-if="childError" title="此页数据加载失败，请刷新重试" type="error" :closable="false"/><el-pagination v-if="['issues','plans','expenses'].includes(active)" v-model:current-page="childPage" :page-size="20" :total="childTotal" layout="total, prev, pager, next" @current-change="loadTab"/><div v-if="canEdit&&['basic','details','registration','notes'].includes(active)" class="zj-project-save"><span class="zj-sub">每页单独保存，避免覆盖其他页面的信息。</span><el-button type="primary" :loading="saving" @click="saveSection">保存{{tabLabels[active]}}</el-button></div></section>
<el-dialog v-model="childOpen" :title="(child.id?'查看 / 编辑':'新增')+(childKind==='issues'?'问题':'计划')" width="min(680px, 96vw)" :close-on-click-modal="false" :before-close="closeChild"><el-form label-position="top" :disabled="!canEdit||childSaving"><el-form-item label="标题" required><el-input v-model="child.title" maxlength="200"/></el-form-item><template v-if="childKind==='issues'"><div class="zj-grid"><el-form-item label="问题程度"><el-select v-model="child.severity"><el-option v-for="x in ['low','medium','high']" :key="x" :label="labels[x]" :value="x"/></el-select></el-form-item><el-form-item label="进展"><el-select v-model="child.status"><el-option v-for="x in ['open','processing','resolved']" :key="x" :label="labels[x]" :value="x"/></el-select></el-form-item><el-form-item label="发现日期"><el-date-picker v-model="child.foundDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="解决日期"><el-date-picker v-model="child.resolvedDate" value-format="YYYY-MM-DD"/></el-form-item></div><el-form-item label="问题描述"><el-input v-model="child.description" type="textarea" :rows="5" maxlength="10000"/></el-form-item><el-form-item label="现场照片 / 附件"><FileUpload v-model="child.files" :disabled="!canEdit" :limit="20" :file-type="['png','jpg','jpeg','pdf','doc','docx']"/></el-form-item></template><template v-else><div class="zj-grid"><el-form-item label="计划类型"><el-select v-model="child.planType"><el-option v-for="x in ['visit','completion','report','other']" :key="x" :label="labels[x]" :value="x"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="child.status"><el-option v-for="x in ['planned','in_progress','done','cancelled']" :key="x" :label="labels[x]" :value="x"/></el-select></el-form-item><el-form-item label="计划开始日期" required><el-date-picker v-model="child.startDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="计划完成日期"><el-date-picker v-model="child.endDate" value-format="YYYY-MM-DD"/></el-form-item></div><el-form-item label="计划说明"><el-input v-model="child.remark" type="textarea" :rows="5" maxlength="5000"/></el-form-item></template></el-form><template #footer><el-button @click="closeChild(()=>childOpen=false)">关闭</el-button><el-button v-if="canEdit" type="primary" :loading="childSaving" @click="saveChild">保存</el-button></template></el-dialog>
</template></main></template>
<script setup name="ZhongjiProjectDetail">
import {onBeforeRouteLeave} from 'vue-router';import {getProject,saveProjectSection,projectChildren,saveProjectChild,deleteProjectChild,applyProjectNumber,projectTypes} from '@/api/workProject';import ProjectBasicForm from './components/ProjectBasicForm.vue';import FileUpload from '@/components/FileUpload/index.vue';import {fileUrl} from '@/utils/files';import auth from '@/plugins/auth';import '@/assets/styles/zhongji.scss';
const route=useRoute(),router=useRouter(),{proxy}=getCurrentInstance();const id=computed(()=>route.params.id),project=ref(),basic=ref({}),basicRef=ref(),details=ref({}),registration=ref({}),notes=ref(''),active=ref('basic'),loading=ref(false),error=ref(false),saving=ref(false);const canEdit=computed(()=>auth.hasPermi('management:project:edit')),canExpenses=computed(()=>auth.hasPermi('management:project:expenses'));const children=reactive({issues:[],plans:[],expenses:[]}),childPage=ref(1),childTotal=ref(0),childLoading=ref(false),childError=ref(false),expenseSummary=ref({}),expenseUsers=ref([]),legacyAmounts=ref([]),childOpen=ref(false),child=ref({}),childKind=ref('issues'),childSaving=ref(false);let snapshots={},childSnapshot='',loadSequence=0;
const tabLabels={basic:'基本信息',details:'详细信息',registration:'登记信息',notes:'备注信息'};const labels={low:'一般',medium:'较严重',high:'严重',open:'待处理',processing:'处理中',resolved:'已解决',visit:'现场作业',completion:'完工',report:'出报告',other:'其他',planned:'待执行',in_progress:'执行中',done:'已完成',cancelled:'已取消'};const detailFields=[{key:'buildingOverview',label:'建筑概况',multi:true},{key:'buildingUse',label:'建筑使用性质'},{key:'buildingArea',label:'建筑面积（㎡）'},{key:'buildingHeight',label:'建筑高度（m）'},{key:'aboveFloors',label:'地上层数'},{key:'belowFloors',label:'地下层数'},{key:'structureType',label:'建筑结构类型'},{key:'serviceScope',label:'服务 / 检测范围',multi:true},{key:'fireFacilities',label:'消防设施概况',multi:true},{key:'reportBasis',label:'报告编制依据',multi:true}];
function value(tab){return JSON.stringify(tab==='basic'?basic.value:tab==='details'?details.value:tab==='registration'?registration.value:notes.value);}const money=x=>Number(x||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
async function load(){loading.value=true;error.value=false;try{project.value=(await getProject(id.value)).data;basic.value={...project.value};details.value=JSON.parse(project.value.detailsJson||'{}');registration.value={visitStatus:'unknown',reportStatus:'unknown',...JSON.parse(project.value.registrationJson||'{}')};notes.value=project.value.remark||'';for(const t of Object.keys(tabLabels))snapshots[t]=value(t);}catch{project.value=null;error.value=true;}finally{loading.value=false;}}
async function allowLeave(){if(saving.value||childSaving.value)return false;if(canEdit.value&&snapshots[active.value]!==undefined&&snapshots[active.value]!==value(active.value)){try{await proxy.$modal.confirm('当前页面有未保存的修改，确认放弃？');const old=JSON.parse(snapshots[active.value]);if(active.value==='basic')basic.value=old;else if(active.value==='details')details.value=old;else if(active.value==='registration')registration.value=old;else notes.value=old;}catch{return false;}}return true;}
async function beforeTab(){if(!await allowLeave())return false;childPage.value=1;childError.value=false;return true;}onBeforeRouteLeave(allowLeave);
async function loadTab(){if(!['issues','plans','expenses'].includes(active.value))return;const n=++loadSequence,kind=active.value;childLoading.value=true;childError.value=false;try{const r=await projectChildren(id.value,kind,{pageNum:childPage.value,pageSize:20});if(n===loadSequence){children[kind]=r.rows;childTotal.value=r.total;if(kind==='expenses'){expenseSummary.value=r.summary;expenseUsers.value=r.users||[];legacyAmounts.value=(r.legacySummary||[]).map(x=>money(JSON.parse(x.snapshotJson).project_cost));}}}catch{if(n===loadSequence){children[kind]=[];childTotal.value=0;childError.value=true;}}finally{if(n===loadSequence)childLoading.value=false;}}
watch(active,()=>childPage.value=1);async function refresh(){if(await allowLeave()){await load();await loadTab();}}function back(){const paths={WB:'maintenance',JC:'inspection',PD:'rating',PG:'assessment',QT:'other'};router.push('/zhongji/projects/'+paths[project.value.projectType]);}
async function saveSection(){if(active.value==='basic'&&!await basicRef.value.validate().catch(()=>false))return;const payload=active.value==='basic'?{...basic.value}:active.value==='details'?{details:details.value}:active.value==='registration'?{registration:registration.value}:{remark:notes.value};saving.value=true;try{await saveProjectSection(id.value,active.value,{...payload,version:project.value.version});proxy.$modal.msgSuccess('已保存');await load();}finally{saving.value=false;}}
async function applyNumber(){if(!await allowLeave())return;await proxy.$modal.confirm('为此历史项目申请正式编号？原编号仍保留备查。');saving.value=true;try{await applyProjectNumber(id.value);await load();proxy.$modal.msgSuccess('已申请正式编号');}finally{saving.value=false;}}
function editChild(kind,row){childKind.value=kind;child.value=row?{...row}:kind==='issues'?{title:'',description:'',severity:'low',status:'open',foundDate:null,resolvedDate:null,files:''}:{title:'',planType:'visit',status:'planned',startDate:null,endDate:null,remark:''};childSnapshot=JSON.stringify(child.value);childOpen.value=true;}
async function closeChild(done){if(childSaving.value)return;if(canEdit.value&&childSnapshot!==JSON.stringify(child.value)){try{await proxy.$modal.confirm('确认放弃未保存的信息？');}catch{return;}}done();}
async function saveChild(){if(!child.value.title?.trim()||(childKind.value==='plans'&&!child.value.startDate)){proxy.$modal.msgError('请填写标题和必填日期');return;}childSaving.value=true;try{await saveProjectChild(id.value,childKind.value,child.value);childOpen.value=false;proxy.$modal.msgSuccess('已保存');await loadTab();}finally{childSaving.value=false;}}
async function removeChild(kind,row){await proxy.$modal.confirm(`确认删除“${row.title}”？`);await deleteProjectChild(id.value,kind,row.id);await loadTab();}watch(()=>route.params.id,()=>{active.value='basic';load();});onMounted(load);
</script>
<style scoped>.zj-project-save{display:flex;justify-content:space-between;align-items:center;gap:16px;border-top:1px solid #e5eaf2;padding-top:20px;margin-top:24px}.zj-workspace :deep(.el-form .el-select),.zj-workspace :deep(.el-form .el-date-editor){width:100%}.zj-workspace :deep(.el-tabs__item){height:48px}@media(max-width:900px){.zj-project-save{align-items:flex-start;flex-direction:column}}</style>
